catalog_script_client.script:
function onLoad() {
    var targetWorkspaceId = '';

    try {
        // 1. Safe lookup using ServiceNow's standard 'top' window parameter chain
        if (typeof top !== 'undefined' && top.location && top.location.search) {
            var urlSearchString = top.location.search;
            var match = urlSearchString.match(/[?&]sysparm_workspace=([^&]+)/);
            if (match && match[1]) {
                targetWorkspaceId = decodeURIComponent(match[1]);
            }
        }
    } catch (err) {
        // Silently catch and suppress sandbox security boundary restrictions
        console.log('Parameter lookup handled via safety fallback.');
    }

    // 2. Pre-populate your field ONLY if a valid workspace ID string was extracted
    if (targetWorkspaceId) {
        // DOUBLE CHECK: Make sure 'select_workspace' matches the backend Name of your variable field!
        g_form.setValue('select_workspace', targetWorkspaceId);
    }
}
